using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEditor;
public static partial class AtelierBuild {
 static int meshSerial;static Dictionary<string,Mesh> meshCache=new Dictionary<string,Mesh>();
 static Vector3 V(float x,float y,float z)=>new Vector3(x,y,z);
 static Transform Group(string name,Transform parent=null,Vector3 position=default(Vector3)){var g=new GameObject(name).transform;g.SetParent(parent,false);g.localPosition=position;return g;}
 static Mesh SaveMesh(Mesh mesh,string key){string path=A+"Meshes/"+key+".asset";mesh.RecalculateBounds();if(mesh.uv.Length==mesh.vertexCount)mesh.RecalculateTangents();var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.indexFormat=mesh.indexFormat;old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;old.tangents=mesh.tangents;old.colors=mesh.colors;old.subMeshCount=mesh.subMeshCount;for(int i=0;i<mesh.subMeshCount;i++)old.SetTriangles(mesh.GetTriangles(i),i);old.bounds=mesh.bounds;old.name=mesh.name;old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static GameObject MeshObject(string name,Transform parent,Mesh mesh,Material material,Vector3 pos=default(Vector3),bool collision=false){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=pos;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=material;if(collision)go.AddComponent<MeshCollider>().sharedMesh=mesh;return go;}
 static Mesh RoundedBox(Vector3 size,float radius){if(size.x<=0||size.y<=0||size.z<=0)throw new ArgumentException("Box dimensions must be positive: "+size);string key="box_"+size.ToString("F3")+"_"+radius.ToString("F3");if(meshCache.TryGetValue(key,out var cached))return cached;radius=Mathf.Min(radius,Mathf.Min(size.x,Mathf.Min(size.y,size.z))*.49f);Vector3 half=size*.5f,core=half-Vector3.one*radius;var vv=new List<Vector3>();var nn=new List<Vector3>();var uv=new List<Vector2>();var tt=new List<int>();for(int axis=0;axis<3;axis++)for(int sign=-1;sign<=1;sign+=2){int u=(axis+1)%3,w=(axis+2)%3;var us=new[]{-half[u],-core[u],core[u],half[u]};var ws=new[]{-half[w],-core[w],core[w],half[w]};int start=vv.Count;for(int j=0;j<4;j++)for(int i=0;i<4;i++){Vector3 p=Vector3.zero;p[axis]=half[axis]*sign;p[u]=us[i];p[w]=ws[j];var c=new Vector3(Mathf.Clamp(p.x,-core.x,core.x),Mathf.Clamp(p.y,-core.y,core.y),Mathf.Clamp(p.z,-core.z,core.z));var n=(p-c).normalized;vv.Add(c+n*radius);nn.Add(n);uv.Add(new Vector2(p[u],p[w]));}for(int j=0;j<3;j++)for(int i=0;i<3;i++){int a=start+j*4+i,b=a+1,c=a+4,d=c+1;if(sign>0)tt.AddRange(new[]{a,b,d,a,d,c});else tt.AddRange(new[]{a,d,b,a,c,d});}}
 var m=new Mesh{name=key};m.SetVertices(vv);m.SetNormals(nn);m.SetUVs(0,uv);m.SetTriangles(tt,0);m=SaveMesh(m,"Shape_"+meshSerial++);meshCache[key]=m;return m;}
 static GameObject Box(string n,Transform p,Vector3 at,Vector3 size,Material mat,float bevel=.015f,bool collision=false){return MeshObject(n,p,RoundedBox(size,bevel),mat,at,collision);}
 static Mesh LatheMesh(Vector2[] profile,int sides=48){var vv=new List<Vector3>();var uv=new List<Vector2>();var tt=new List<int>();for(int k=0;k<profile.Length;k++)for(int i=0;i<=sides;i++){float a=i*2*Mathf.PI/sides;vv.Add(new Vector3(Mathf.Cos(a)*profile[k].x,profile[k].y,Mathf.Sin(a)*profile[k].x));uv.Add(new Vector2(i/(float)sides,k/(float)(profile.Length-1)));}for(int k=0;k<profile.Length-1;k++)for(int i=0;i<sides;i++){int a=k*(sides+1)+i,b=a+1,c=a+sides+1,d=c+1;tt.AddRange(new[]{a,c,d,a,d,b});}var m=new Mesh();m.SetVertices(vv);m.SetUVs(0,uv);m.SetTriangles(tt,0);m.RecalculateNormals();return SaveMesh(m,"Lathe_"+meshSerial++);}
 static GameObject Lathe(string name,Transform parent,Vector3 pos,Vector2[] profile,Material mat,int sides=48){return MeshObject(name,parent,LatheMesh(profile,sides),mat,pos);}
 static GameObject Cylinder(string name,Transform parent,Vector3 a,Vector3 b,float radius,Material mat,int sides=20){float length=Vector3.Distance(a,b);string key="cyl_"+radius.ToString("F3")+"_"+length.ToString("F3")+"_"+sides;if(!meshCache.TryGetValue(key,out var m)){m=LatheMesh(new[]{new Vector2(0,0),new Vector2(radius,0),new Vector2(radius,length),new Vector2(0,length)},sides);meshCache[key]=m;}var go=MeshObject(name,parent,m,mat,a);go.transform.localRotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);return go;}
 static void Bolt(Transform parent,Vector3 point,Vector3 normal,float r=.018f){Cylinder("Hex fastener",parent,point,point+normal*r*.65f,r,steel,6);}
 static GameObject Tube(string name,Transform parent,Vector3[] points,float r,Material mat,int sides=12){var vs=new List<Vector3>();var ns=new List<Vector3>();var uv=new List<Vector2>();var ts=new List<int>();for(int i=0;i<points.Length;i++){var tangent=(points[Mathf.Min(points.Length-1,i+1)]-points[Mathf.Max(0,i-1)]).normalized;var right=Vector3.Cross(tangent,Mathf.Abs(tangent.y)>.92f?Vector3.forward:Vector3.up).normalized;var up=Vector3.Cross(right,tangent).normalized;for(int k=0;k<=sides;k++){float a=k*2*Mathf.PI/sides;var n=right*Mathf.Cos(a)+up*Mathf.Sin(a);vs.Add(points[i]+n*r);ns.Add(n);uv.Add(new Vector2(k/(float)sides,i*.2f));}if(i>0)for(int k=0;k<sides;k++){int a=(i-1)*(sides+1)+k,b=a+1,c=a+sides+1,d=c+1;ts.AddRange(new[]{a,d,b,a,c,d});}}
 var mesh=new Mesh();mesh.SetVertices(vs);mesh.SetNormals(ns);mesh.SetUVs(0,uv);mesh.SetTriangles(ts,0);return MeshObject(name,parent,SaveMesh(mesh,"Tube_"+meshSerial++),mat);}
 static Vector3[] PanelOutline(float x,float y,float z,float width,float height,float radius){var points=new List<Vector3>();for(int corner=0;corner<4;corner++){float cx=x+(corner==0||corner==3?1:-1)*(width*.5f-radius),cy=y+(corner<2?1:-1)*(height*.5f-radius);for(int j=0;j<=6;j++){float a=(corner*90+j*15)*Mathf.Deg2Rad;points.Add(new Vector3(cx+radius*Mathf.Cos(a),cy+radius*Mathf.Sin(a),z));}}points.Add(points[0]);return points.ToArray();}
 static void MergeStatic(Transform parent){var groups=parent.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.gameObject.activeSelf&&r.sharedMaterials.Length==1&&r.sharedMaterial.renderQueue<2500&&r.GetComponent<MeshFilter>()&&!r.GetComponentInParent<AtelierControl>()&&!r.GetComponentInParent<TMPro.TMP_Text>()).GroupBy(r=>r.sharedMaterial).ToArray();foreach(var group in groups){var list=group.ToArray();if(list.Length<3)continue;var mesh=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(list.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=parent.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray(),true,true);MeshObject("Combined_"+group.Key.name,parent,SaveMesh(mesh,"Combined_"+meshSerial++),group.Key);foreach(var r in list){UnityEngine.Object.DestroyImmediate(r.GetComponent<MeshFilter>());UnityEngine.Object.DestroyImmediate(r);}}}
}
